    async def create_enrollment(
        self,
        *,
        idempotency_key: str,
        zasp_fresh_auth: CreateEnrollmentSensorsRequestXZaspFreshAuth,
        name: str,
        kind: SensorKind,
        mode: SensorMode,
        csrf_token: typing.Optional[str] = None,
        zasp_sensor_enrollment_schema: typing.Optional[
            CreateEnrollmentSensorsRequestXZaspSensorEnrollmentSchema
        ] = None,
        runtime_sensor_id: typing.Optional[ProductId] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> SensorEnrollment:
        """
        BrowserSession requests require fresh authentication, same-origin Origin, and CSRF. ProductAPIToken requests omit the browser-only headers. Exact replay never reveals token material and returns conflict so the caller can rotate with a new key.

        Parameters
        ----------
        idempotency_key : str
            Caller-generated key binding an exact workflow mutation and its durable response.

        zasp_fresh_auth : CreateEnrollmentSensorsRequestXZaspFreshAuth
            Explicit fresh-auth confirmation required for a sensitive approval or connector authorization mutation.

        name : str

        kind : SensorKind

        mode : SensorMode

        csrf_token : typing.Optional[str]
            Required for BrowserSession mutations and omitted for ProductAPIToken mutations. The value is bound to the authenticated browser session.

        zasp_sensor_enrollment_schema : typing.Optional[CreateEnrollmentSensorsRequestXZaspSensorEnrollmentSchema]
            Select enrollment-binding-v1 to require a scoped installation binding in a successful one-time credential response. Omission preserves the legacy representation. This is not authentication or mutation intent.

        runtime_sensor_id : typing.Optional[ProductId]
            Optional immutable pairing for OTLP only. Must identify an active Tetragon enrollment in the same scope. Omit for an unpaired semantic source. Event payloads cannot select this authority.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        SensorEnrollment
            Sensor created and token revealed once.

        Examples
        --------
        import asyncio

        from zasp import AsyncZasp

        client = AsyncZasp(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.sensors.create_enrollment(
                idempotency_key="Idempotency-Key",
                zasp_fresh_auth="confirmed",
                name="name",
                kind="tetragon",
                mode="metadata_only",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_enrollment(
            idempotency_key=idempotency_key,
            zasp_fresh_auth=zasp_fresh_auth,
            name=name,
            kind=kind,
            mode=mode,
            csrf_token=csrf_token,
            zasp_sensor_enrollment_schema=zasp_sensor_enrollment_schema,
            runtime_sensor_id=runtime_sensor_id,
            request_options=request_options,
        )
        return _response.data

